1	package qwen
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8	
9		"strix-halo-vulkan/safetensors"
10	)
11	
12	// Config mirrors the text encoder's config.json.
13	type Config struct {
14		HiddenSize       int     `json:"hidden_size"`
15		IntermediateSize int     `json:"intermediate_size"`
16		NumLayers        int     `json:"num_hidden_layers"`
17		NumHeads         int     `json:"num_attention_heads"`
18		NumKVHeads       int     `json:"num_key_value_heads"`
19		HeadDim          int     `json:"head_dim"`
20		VocabSize        int     `json:"vocab_size"`
21		RMSEps           float64 `json:"rms_norm_eps"`
22		RopeTheta        float64 `json:"rope_theta"`
23	
24		// Prefix is what a tensor name starts with in this checkpoint, used
25		// verbatim and empty for none. It is not in config.json, because it is
26		// not a property of the architecture: Z-Image ships its text encoder as
27		// a `Qwen3ForCausalLM` and names every tensor `model.layers.0…`, which
28		// is what LoadConfig fills in, while Qwen3-Embedding ships the same
29		// layers as a bare `Qwen3Model` and names them `layers.0…`, which is
30		// `embed.LoadConfig` clearing this. Same weights, same loader, one
31		// string apart.
32		Prefix string `json:"-"`
33	}
34	
35	// LoadConfig reads a text encoder checkpoint's config.json.
36	func LoadConfig(dir string) (*Config, error) {
37		buf, err := os.ReadFile(filepath.Join(dir, "config.json"))
38		if err != nil {
39			return nil, err
40		}
41		var c Config
42		if err := json.Unmarshal(buf, &c); err != nil {
43			return nil, fmt.Errorf("qwen: parsing config.json: %w", err)
44		}
45		if c.HiddenSize == 0 || c.NumLayers == 0 || c.HeadDim == 0 {
46			return nil, fmt.Errorf("qwen: config.json is missing hidden_size, num_hidden_layers or head_dim")
47		}
48		c.Prefix = "model."
49		return &c, nil
50	}
51	
52	// EncoderLayers is how many of the model's layers the pipeline needs.
53	//
54	// ZImagePipeline._encode_prompt takes `hidden_states[-2]`, and a
55	// hidden_states tuple is the embedding output followed by each layer's
56	// output, so [-2] is layer NumLayers-2's output: the last layer never runs,
57	// the final norm never runs, and there is no lm_head. That is 35 of 36
58	// layers here, worth 2.8% of the compute and 111 M of the 4.02 B parameters.
59	func (c *Config) EncoderLayers() int { return c.NumLayers - 1 }
60	
61	// loader pulls named tensors as float32, holding the first error.
62	type loader struct {
63		set *safetensors.Set
64		err error
65	}
66	
67	func (l *loader) f32(name string) []float32 {
68		if l.err != nil {
69			return nil
70		}
71		t, err := l.set.Get(name)
72		if err != nil {
73			l.err = err
74			return nil
75		}
76		v, err := t.F32(nil)
77		if err != nil {
78			l.err = err
79		}
80		return v
81	}
82	
83	func (l *loader) shape(name string) []int {
84		if l.err != nil {
85			return nil
86		}
87		t, err := l.set.Get(name)
88		if err != nil {
89			l.err = err
90			return nil
91		}
92		return t.Shape
93	}
94	
95	func (l *loader) linear(prefix string) *Linear {
96		sh := l.shape(prefix + ".weight")
97		if l.err != nil {
98			return nil
99		}
100		if len(sh) != 2 {
101			l.err = fmt.Errorf("qwen: %s.weight has shape %v, want 2 dims", prefix, sh)
102			return nil
103		}
104		return &Linear{Out: sh[0], In: sh[1], Weight: l.f32(prefix + ".weight")}
105	}
106	
107	func (l *loader) rms(name string, eps float64) *RMSNorm {
108		return &RMSNorm{Weight: l.f32(name + ".weight"), Eps: eps}
109	}
110	
111	// Load reads the text encoder. layers is how many decoder layers to bring
112	// in, counted from 0; pass cfg.EncoderLayers() for what the pipeline uses
113	// and cfg.NumLayers for the whole model. The weights land as float32, which
114	// is 404 MB per layer -- this is the oracle, not the fast path.
115	func Load(dir string, layers int) (*Model, error) {
116		cfg, err := LoadConfig(dir)
117		if err != nil {
118			return nil, err
119		}
120		return LoadWith(dir, cfg, layers)
121	}
122	
123	// LoadWith is Load against a config the caller already holds, which is how a
124	// checkpoint that names its tensors differently gets in (Config.Prefix).
125	func LoadWith(dir string, cfg *Config, layers int) (*Model, error) {
126		if layers <= 0 || layers > cfg.NumLayers {
127			return nil, fmt.Errorf("qwen: asked for %d of %d layers", layers, cfg.NumLayers)
128		}
129		set, err := safetensors.OpenSet(dir)
130		if err != nil {
131			return nil, err
132		}
133		defer set.Close()
134	
135		m := &Model{Cfg: cfg}
136		if m.Rows, m.Embed, err = LoadEmbedding(set, cfg); err != nil {
137			return nil, err
138		}
139		for i := 0; i < layers; i++ {
140			l, err := LoadLayer(set, i, cfg)
141			if err != nil {
142				return nil, err
143			}
144			m.Layers = append(m.Layers, l)
145		}
146		return m, nil
147	}
148	
149	// LoadEmbedding reads the token embedding table as float32, returning its row
150	// count alongside it -- vocab_size is padded above the tokenizer's id space,
151	// and the table is the authority on how far.
152	func LoadEmbedding(set *safetensors.Set, cfg *Config) (int, []float32, error) {
153		l := &loader{set: set}
154		name := cfg.Prefix + embedName
155		shape := l.shape(name)
156		if l.err != nil {
157			return 0, nil, l.err
158		}
159		if len(shape) != 2 || shape[1] != cfg.HiddenSize {
160			return 0, nil, fmt.Errorf("qwen: %s is %v, want [rows %d]", name, shape, cfg.HiddenSize)
161		}
162		data := l.f32(name)
163		return shape[0], data, l.err
164	}
