84	}
85	
86	// Linear is y = W x with W stored [Out, In], PyTorch's order. Qwen3 has
87	// attention_bias false and no bias anywhere else either, so there is no bias
88	// term here at all.
89	type Linear struct {
90		In, Out int
91		Weight  []float32
92	}
93	
94	// Apply runs the projection over every row of x.
95	func (l *Linear) Apply(x *Mat) (*Mat, error) {
96		if x.Cols != l.In {
97			return nil, fmt.Errorf("qwen: linear takes %d features, got %d", l.In, x.Cols)
98		}
99		out := NewMat(x.Rows, l.Out)
100		parallelFor(l.Out, func(o int) {
101			w := l.Weight[o*l.In : (o+1)*l.In]
102			for r := 0; r < x.Rows; r++ {
103				row := x.Row(r)
104				var sum float32
105				for i, wv := range w {
106					sum += wv * row[i]
107				}
108				out.Data[r*l.Out+o] = sum
109			}
110		})
111		return out, nil
112	}
113	
114	// RMSNorm is x * rsqrt(mean(x^2) + eps) * weight over the last len(Weight)
115	// components of a row. As in the DiT, a row several times that width is
116	// normalised span by span, which is what makes the q and k norms *per head*.
117	//
118	// transformers computes the reduction in float32 and multiplies the weight
119	// in the input dtype; everything here is float32 already, so there is no
120	// cast to reproduce.
121	type RMSNorm struct {
122		Weight []float32
123		Eps    float64
124	}
125	
126	// Apply returns a normalised copy.
127	func (n *RMSNorm) Apply(x *Mat) (*Mat, error) {
128		out := x.Clone()
129		if err := n.ApplyInPlace(out); err != nil {
130			return nil, err
131		}
132		return out, nil
133	}
134	
135	// ApplyInPlace normalises every span of len(Weight) in every row.
136	func (n *RMSNorm) ApplyInPlace(x *Mat) error {
137		w := len(n.Weight)
138		if w == 0 || x.Cols%w != 0 {
139			return fmt.Errorf("qwen: rms norm of width %d does not divide %d columns", w, x.Cols)
140		}
141		spans := x.Cols / w
142		parallelFor(x.Rows, func(r int) {
143			row := x.Row(r)
144			for s := 0; s < spans; s++ {
145				span := row[s*w : (s+1)*w]
146				var sum float64
147				for _, v := range span {
148					sum += float64(v) * float64(v)
149				}
150				scale := float32(1 / math.Sqrt(sum/float64(w)+n.Eps))
151				for i := range span {
152					span[i] *= scale * n.Weight[i]
153				}
154			}
155		})
156		return nil
157	}
158	
159	// RoPE holds the rotary tables for one sequence length.
160	//
161	// transformers builds cos and sin as cat(freqs, freqs) over the full head
162	// width; only half of that is distinct, so this keeps the half and Apply
163	// indexes it twice. Positions are 0..T-1: the encoder sees one sequence with
164	// no cache.
165	type RoPE struct {
166		HeadDim  int
167		Cos, Sin []float32 // [T, HeadDim/2]
168	}
169	
170	// NewRoPE builds the tables for T positions.
171	func NewRoPE(headDim, T int, theta float64) *RoPE {
172		half := headDim / 2
173		r := &RoPE{HeadDim: headDim, Cos: make([]float32, T*half), Sin: make([]float32, T*half)}
174		for i := 0; i < half; i++ {
175			freq := 1 / math.Pow(theta, float64(2*i)/float64(headDim))
176			for p := 0; p < T; p++ {
177				angle := float64(p) * freq
178				r.Cos[p*half+i] = float32(math.Cos(angle))
179				r.Sin[p*half+i] = float32(math.Sin(angle))
180			}
181		}
182		return r
183	}
184	
185	// Apply rotates every head of every row in place. x is [T, heads*HeadDim].
186	//
187	// The pairing is NeoX's: component i moves against component i+half, not
188	// against its neighbour. Getting this wrong leaves the norms and the
189	// magnitudes intact and only the attention pattern wrong, which is why it is
190	// checked against a dumped q_roped rather than eyeballed.
191	func (r *RoPE) Apply(x *Mat) error {
192		half := r.HeadDim / 2
193		if x.Cols%r.HeadDim != 0 {
194			return fmt.Errorf("qwen: rope of head dim %d does not divide %d columns", r.HeadDim, x.Cols)
195		}
196		if x.Rows*half > len(r.Cos) {
197			return fmt.Errorf("qwen: rope table holds %d positions, need %d", len(r.Cos)/half, x.Rows)
198		}
199		heads := x.Cols / r.HeadDim
200		parallelFor(x.Rows, func(p int) {
201			cos, sin := r.Cos[p*half:(p+1)*half], r.Sin[p*half:(p+1)*half]
202			row := x.Row(p)
203			for h := 0; h < heads; h++ {
204				head := row[h*r.HeadDim : (h+1)*r.HeadDim]
205				for i := 0; i < half; i++ {
206					lo, hi := head[i], head[i+half]
207					head[i] = lo*cos[i] - hi*sin[i]
208					head[i+half] = hi*cos[i] + lo*sin[i]
209				}
210			}
211		})
212		return nil
213	}
214	
215	// silu is x * sigmoid(x), Qwen3's hidden_act.
216	func silu(x float32) float32 {
217		return x / (1 + float32(math.Exp(float64(-x))))
218	}
219	
220	// Attention is causal grouped-query attention over one sequence.
221	//
222	// q is [T, heads*headDim] and k, v are [T, kvHeads*headDim]; each key/value
223	// head serves heads/kvHeads consecutive query heads, which is
224	// repeat_interleave and not a tile.
225	func Attention(q, k, v *Mat, heads, kvHeads, headDim int) (*Mat, error) {
226		T := q.Rows
227		if k.Rows != T || v.Rows != T {
228			return nil, fmt.Errorf("qwen: attention got %d q rows against %d k and %d v", T, k.Rows, v.Rows)
229		}
230		if q.Cols != heads*headDim || k.Cols != kvHeads*headDim || v.Cols != kvHeads*headDim {
231			return nil, fmt.Errorf("qwen: attention shapes %s %s %s do not match %d/%d heads of %d",
232				q, k, v, heads, kvHeads, headDim)
233		}
234		if heads%kvHeads != 0 {
235			return nil, fmt.Errorf("qwen: %d heads do not divide into %d kv heads", heads, kvHeads)
236		}
237		rep := heads / kvHeads
238		scale := float32(1 / math.Sqrt(float64(headDim)))
239		out := NewMat(T, heads*headDim)
240		parallelFor(heads, func(h int) {
241			kv := h / rep
242			scores := make([]float32, T)
243			for t := 0; t < T; t++ {
244				qv := q.Row(t)[h*headDim : (h+1)*headDim]
245				// Causal: position t attends to 0..t and nothing later, so the
246				// masked scores are never formed rather than set to -inf.
247				max := float32(math.Inf(-1))
248				for s := 0; s <= t; s++ {
249					kvRow := k.Row(s)[kv*headDim : (kv+1)*headDim]
250					var dot float32
251					for i, qi := range qv {
252						dot += qi * kvRow[i]
253					}
254					scores[s] = dot * scale
255					if scores[s] > max {
256						max = scores[s]
257					}
258				}
259				var sum float32
260				for s := 0; s <= t; s++ {
261					scores[s] = float32(math.Exp(float64(scores[s] - max)))
262					sum += scores[s]
263				}
264				dst := out.Row(t)[h*headDim : (h+1)*headDim]
265				for s := 0; s <= t; s++ {
266					p := scores[s] / sum
267					vRow := v.Row(s)[kv*headDim : (kv+1)*headDim]
268					for i, vv := range vRow {
269						dst[i] += p * vv
270					}
271				}
272			}
273		})
274		return out, nil
275	}
276	
277	// Trace collects named intermediates of a forward pass. A nil Trace costs
278	// nothing; a non-nil one is how a stagewise test walks the graph against the
279	// reference dump.
280	type Trace map[string]*Mat
281	
282	func (tr Trace) put(name string, m *Mat) {
283		if tr != nil {
284			tr[name] = m.Clone()
285		}
286	}
287	
288	// Layer is one Qwen3 decoder layer.
289	type Layer struct {
290		AttnNorm *RMSNorm
291		Q, K, V  *Linear
292		QNorm    *RMSNorm // per head, over head_dim
293		KNorm    *RMSNorm
294		O        *Linear
295		FFNNorm  *RMSNorm
296		Gate     *Linear
297		Up       *Linear
298		Down     *Linear
299	
300		Heads, KVHeads, HeadDim int
301	}
302	
303	// Forward runs the layer: pre-norm attention with a residual, then pre-norm
304	// SwiGLU with a residual. prefix names the trace entries.
305	func (l *Layer) Forward(x *Mat, rope *RoPE, tr Trace, prefix string) (*Mat, error) {
306		normed, err := l.AttnNorm.Apply(x)
307		if err != nil {
308			return nil, err
309		}
310		tr.put(prefix+"input_layernorm", normed)
311	
312		q, err := l.Q.Apply(normed)
313		if err != nil {
314			return nil, err
315		}
316		k, err := l.K.Apply(normed)
317		if err != nil {
318			return nil, err
319		}
320		v, err := l.V.Apply(normed)
321		if err != nil {
322			return nil, err
323		}
324		tr.put(prefix+"q", q)
325		tr.put(prefix+"k", k)
326		tr.put(prefix+"v", v)
327	
328		// The q/k norms are per head: the weight is [head_dim] and the row holds
329		// every head, so ApplyInPlace normalises each head's span on its own.
330		if err := l.QNorm.ApplyInPlace(q); err != nil {
331			return nil, err
332		}
333		if err := l.KNorm.ApplyInPlace(k); err != nil {
334			return nil, err
335		}
336		tr.put(prefix+"q_normed", q)
337		tr.put(prefix+"k_normed", k)
338	
339		if err := rope.Apply(q); err != nil {
340			return nil, err
341		}
342		if err := rope.Apply(k); err != nil {
343			return nil, err
344		}
345		tr.put(prefix+"q_roped", q)
346		tr.put(prefix+"k_roped", k)
347	
348		ctx, err := Attention(q, k, v, l.Heads, l.KVHeads, l.HeadDim)
349		if err != nil {
350			return nil, err
351		}
352		tr.put(prefix+"attn_ctx", ctx)
353	
354		attn, err := l.O.Apply(ctx)
355		if err != nil {
356			return nil, err
357		}
358		tr.put(prefix+"attn_out", attn)
359	
360		resid := x.Clone()
361		for i, v := range attn.Data {
362			resid.Data[i] += v
363		}
364		tr.put(prefix+"resid1", resid)
365	
366		normed2, err := l.FFNNorm.Apply(resid)
