52	func loadManifest(t *testing.T) *manifest {
53		t.Helper()
54		buf, err := os.ReadFile(filepath.Join(refDir, "manifest.json"))
55		if err != nil {
56			t.Skipf("no reference dump in %s (%v); run reference/dump_qwen.py", refDir, err)
57		}
58		var m manifest
59		if err := json.Unmarshal(buf, &m); err != nil {
60			t.Fatal(err)
61		}
62		m.dir = refDir
63		return &m
64	}
65	
66	// loadRef reads a dumped tensor, flattening every leading axis into rows.
67	func loadRef(t *testing.T, m *manifest, name string) *Mat {
68		t.Helper()
69		meta, ok := m.Tensors[name]
70		if !ok {
71			t.Fatalf("reference has no tensor %q", name)
72		}
73		raw, err := os.ReadFile(filepath.Join(m.dir, name+".bin"))
74		if err != nil {
75			t.Fatal(err)
76		}
77		if len(raw) != meta.Count*4 {
78			t.Fatalf("%s: %d bytes for %d float32", name, len(raw), meta.Count)
79		}
80		data := make([]float32, meta.Count)
81		for i := range data {
82			data[i] = math.Float32frombits(binary.LittleEndian.Uint32(raw[i*4:]))
83		}
84		cols := meta.Shape[len(meta.Shape)-1]
85		return &Mat{Rows: meta.Count / cols, Cols: cols, Data: data}
86	}
87	
88	// relTol is the bound every stage must stay inside, set the way the VAE's
89	// and the DiT's were: from the measured legitimate drift, with
90	// TestValidationDetectsErrors pinning the other side. Both sides are fp32
91	// here, so the only drift is summation order.
92	const relTol = 2e-4
93	
94	// deviation reports the largest absolute error and that error normalised by
95	// max(|want|, rms) at the element it lands on.
96	//
97	// The DiT's tests normalise by the tensor's RMS alone. That does not survive
98	// this model: Qwen3's hidden states carry massive activations -- `hidden_2`
99	// has an absmax of 59.8 against an RMS of 0.55, and `final` 13753 against
100	// 59.5 -- so a float32 summation-order difference on one of those outliers
101	// is 9e-6 of the element it sits on and 7e-4 of the tensor's RMS, and only
102	// the second number looks like a bug. The floor keeps the RMS as the
103	// denominator for the elements near zero, where dividing by the element
104	// itself would be meaningless.
105	func deviation(got, want *Mat) (maxAbs, rms, rel float64, worst int) {
106		var sumSq float64
107		for i := range want.Data {
108			w := float64(want.Data[i])
109			sumSq += w * w
110		}
111		rms = math.Sqrt(sumSq / float64(len(want.Data)))
112		for i := range want.Data {
113			g, w := float64(got.Data[i]), float64(want.Data[i])
114			d := math.Abs(g - w)
115			if d > maxAbs {
116				maxAbs = d
117			}
118			if r := d / math.Max(math.Abs(w), math.Max(rms, 1e-12)); r > rel {
119				rel, worst = r, i
120			}
121		}
122		return maxAbs, rms, rel, worst
123	}
