125	// compare asserts a computed tensor matches the reference.
126	func compare(t *testing.T, name string, got, want *Mat) {
127		t.Helper()
128		if got.Rows != want.Rows || got.Cols != want.Cols {
129			t.Fatalf("%s: shape %s, want %s", name, got, want)
130		}
131		maxAbs, rms, rel, worst := deviation(got, want)
132		if rel > relTol {
133			t.Errorf("%s %s: max abs %.6g, worst rel %.3g at %d (got %g want %g), rms %.6g > %.0e",
134				name, got, maxAbs, rel, worst, got.Data[worst], want.Data[worst], rms, relTol)
135			return
136		}
137		t.Logf("%-26s %-14s max abs %.3g  rms %.4g  rel %.2g", name, got.String(), maxAbs, rms, rel)
138	}
