155	func TestConfig(t *testing.T) {
156		m := loadManifest(t)
157		cfg, err := LoadConfig(encoder)
158		if err != nil {
159			t.Skipf("no text encoder checkpoint at %s (%v)", encoder, err)
160		}
161		for _, c := range []struct {
162			name      string
163			got, want int
164		}{
165			{"hidden_size", cfg.HiddenSize, m.HiddenSize},
166			{"layers", cfg.NumLayers, m.Layers},
167			{"heads", cfg.NumHeads, m.Heads},
168			{"kv_heads", cfg.NumKVHeads, m.KVHeads},
169			{"head_dim", cfg.HeadDim, m.HeadDim},
170		} {
171			if c.got != c.want {
172				t.Errorf("%s is %d, want %d", c.name, c.got, c.want)
173			}
174		}
175		if cfg.EncoderLayers() != cfg.NumLayers-1 {
176			t.Errorf("EncoderLayers is %d, want %d", cfg.EncoderLayers(), cfg.NumLayers-1)
177		}
178		// Both are exact zeros in the dump; anything else means the assumptions
179		// this package is built on stopped holding.
180		if m.Minus2Gap != 0 {
181			t.Errorf("hidden_states[-2] is not %d layers by hand: gap %g", cfg.NumLayers-1, m.Minus2Gap)
182		}
183		if m.PadGap != 0 {
184			t.Errorf("padding to 512 changed the hidden states by %g; Forward skips the padding", m.PadGap)
185		}
186		t.Logf("%d layers, %d of which the pipeline runs; padding to 512 costs %g",
187			cfg.NumLayers, cfg.EncoderLayers(), m.PadGap)
188	}
189	
190	// TestTokenizer checks that the Go tokenizer produces the ids the reference
191	// ran, which is what makes the two halves of this stage one pipeline.
192	func TestTokenizer(t *testing.T) {
193		m := loadManifest(t)
194		tok, err := tokenizer.Load(tokDir)
195		if err != nil {
196			t.Skipf("no tokenizer at %s (%v)", tokDir, err)
197		}
198		for _, c := range []struct {
199			prompt string
200			want   []int32
201		}{{m.Prompt, m.IDs}, {m.Prompt2, m.IDs2}} {
202			got, err := tok.EncodePrompt(c.prompt)
203			if err != nil {
204				t.Fatal(err)
205			}
206			if len(got) != len(c.want) {
207				t.Fatalf("%q: %d ids, want %d", c.prompt, len(got), len(c.want))
208			}
209			for i := range got {
210				if got[i] != c.want[i] {
211					t.Fatalf("%q: id %d is %d, want %d", c.prompt, i, got[i], c.want[i])
212				}
213			}
214			t.Logf("%d ids for %q", len(got), c.prompt)
215		}
216	}
217	
218	// TestRoPETable checks the rotary table before anything uses it. The dump
219	// holds transformers' cat(freqs, freqs) over the full head width; this keeps
220	// only the distinct half, so the check is that the half repeats.
221	func TestRoPETable(t *testing.T) {
222		m := loadManifest(t)
223		cos, sin := loadRef(t, m, "cos"), loadRef(t, m, "sin")
224		rope := NewRoPE(m.HeadDim, m.Seq, m.RopeTheta)
225		half := m.HeadDim / 2
226		gotCos, gotSin := NewMat(m.Seq, m.HeadDim), NewMat(m.Seq, m.HeadDim)
227		for p := 0; p < m.Seq; p++ {
228			for i := 0; i < half; i++ {
229				gotCos.Row(p)[i] = rope.Cos[p*half+i]
230				gotCos.Row(p)[i+half] = rope.Cos[p*half+i]
231				gotSin.Row(p)[i] = rope.Sin[p*half+i]
232				gotSin.Row(p)[i+half] = rope.Sin[p*half+i]
233			}
234		}
235		compare(t, "cos", gotCos, cos)
236		compare(t, "sin", gotSin, sin)
237	}
238	
239	// TestLayer walks one decoder layer stage by stage. It is the test that says
240	// which piece is wrong when the encoder's output is; the end-to-end check
241	// below only says that something is.
242	func TestLayer(t *testing.T) {
243		model, m := loadModel(t, m0Layers)
244		if m.DumpLayer != 0 {
245			t.Skipf("the dump is of layer %d and this test loads layer 0", m.DumpLayer)
246		}
247		tr := Trace{}
248		got, err := model.Forward(m.IDs, tr)
249		if err != nil {
250			t.Fatal(err)
251		}
252		compare(t, "embeddings", tr["embeddings"], loadRef(t, m, "embeddings"))
253		for _, name := range []string{
254			"input_layernorm", "q", "k", "v", "q_normed", "k_normed",
255			"q_roped", "k_roped", "attn_ctx", "attn_out", "resid1",
256			"post_attention_layernorm", "mlp", "layer_out",
257		} {
258			compare(t, name, tr["layer0."+name], loadRef(t, m, name))
259		}
260		compare(t, "hidden_1", got, loadRef(t, m, "hidden_1"))
261	}
262	
263	// m0Layers is one layer: everything TestLayer needs, and 448 MB rather than
264	// 15.7 GB.
265	const m0Layers = 1
266	
267	// TestEncoder runs what the pipeline runs -- 35 of the 36 layers, no final
268	// norm -- against the hidden state it hands the DiT, for two prompts. This
269	// is the stage's acceptance check.
270	func TestEncoder(t *testing.T) {
271		if testing.Short() {
272			t.Skip("loads 15.7 GB of fp32 weights")
273		}
274		m := loadManifest(t)
275		cfg, err := LoadConfig(encoder)
276		if err != nil {
277			t.Skipf("no text encoder checkpoint at %s (%v)", encoder, err)
278		}
279		model, err := Load(encoder, cfg.EncoderLayers())
280		if err != nil {
281			t.Fatal(err)
282		}
283		tr := Trace{}
284		got, err := model.Forward(m.IDs, tr)
285		if err != nil {
286			t.Fatal(err)
287		}
288		// The intermediate hidden states first: a drift that only shows up deep
289		// in the stack is a different bug from one present at layer 2.
290		compare(t, "hidden_1", tr["hidden_1"], loadRef(t, m, "hidden_1"))
291		compare(t, "hidden_2", tr["hidden_2"], loadRef(t, m, "hidden_2"))
292		compare(t, "hidden_18", tr["hidden_18"], loadRef(t, m, "hidden_18"))
293		compare(t, "final", got, loadRef(t, m, "final"))
294		// And the pipeline's own output, which is the padded run masked back
295		// down -- the same tensor, by the dump's measurement.
296		compare(t, "pipeline_out", got, loadRef(t, m, "pipeline_out"))
297	
298		got2, err := model.Forward(m.IDs2, nil)
299		if err != nil {
300			t.Fatal(err)
301		}
302		compare(t, "final2", got2, loadRef(t, m, "final2"))
303	}
304	
305	// TestValidationDetectsErrors is the negative control. The four
306	// perturbations are the mistakes this model actually invites: the two rotary
307	// conventions look equally plausible and the DiT next door uses the other
308	// one, the q/k norms are per head rather than over the full width, grouped
309	// query heads can be mapped to their kv head two ways, and a causal mask is
310	// invisible in every shape.
311	func TestValidationDetectsErrors(t *testing.T) {
312		model, m := loadModel(t, m0Layers)
313		l := model.Layers[0]
314		heads, kvHeads, hd := l.Heads, l.KVHeads, l.HeadDim
315		normed := loadRef(t, m, "input_layernorm")
316	
317		t.Run("rope paired adjacent not by halves", func(t *testing.T) {
318			q := loadRef(t, m, "q_normed")
319			rope := NewRoPE(hd, m.Seq, m.RopeTheta)
320			applyRoPEAdjacent(rope, q, heads, hd)
321			assertCaught(t, q, loadRef(t, m, "q_roped"))
322		})
323	
324		t.Run("qk norm over full width not per head", func(t *testing.T) {
325			q, err := l.Q.Apply(normed)
326			if err != nil {
327				t.Fatal(err)
328			}
329			// The same weights tiled to the full width: one RMS over all 4096
330			// components instead of thirty-two over 128 each.
331			wide := make([]float32, q.Cols)
332			for i := range wide {
333				wide[i] = l.QNorm.Weight[i%hd]
334			}
335			bad := &RMSNorm{Weight: wide, Eps: l.QNorm.Eps}
336			if err := bad.ApplyInPlace(q); err != nil {
337				t.Fatal(err)
338			}
339			assertCaught(t, q, loadRef(t, m, "q_normed"))
340		})
341	
342		t.Run("gqa heads tiled not repeated", func(t *testing.T) {
343			ctx := attentionVariant(t, m, heads, kvHeads, hd, func(h int) int { return h % kvHeads }, true)
344			assertCaught(t, ctx, loadRef(t, m, "attn_ctx"))
345		})
346	
347		t.Run("attention not causal", func(t *testing.T) {
348			ctx := attentionVariant(t, m, heads, kvHeads, hd, func(h int) int { return h / (heads / kvHeads) }, false)
349			assertCaught(t, ctx, loadRef(t, m, "attn_ctx"))
350		})
351	}
352	
353	// assertCaught fails if a deliberately broken tensor slips under relTol.
354	func assertCaught(t *testing.T, got, want *Mat) {
355		t.Helper()
356		maxAbs, rms, rel, _ := deviation(got, want)
357		if rel <= relTol {
358			t.Errorf("perturbation NOT caught: max abs %.6g, rms %.6g, rel %.3g <= %.0e", maxAbs, rms, rel, relTol)
359			return
360		}
361		t.Logf("caught: rel %.3g (%.0fx the %.0e bound)", rel, rel/relTol, relTol)
362	}
363	
364	// applyRoPEAdjacent is the *other* rotary convention -- pairing component 2j
365	// with 2j+1, which is what the DiT uses. Both are in the wild and they
366	// differ only in index arithmetic, so this exists to prove the test can tell
367	// them apart.
368	func applyRoPEAdjacent(r *RoPE, x *Mat, heads, headDim int) {
369		half := headDim / 2
370		for p := 0; p < x.Rows; p++ {
371			row := x.Row(p)
372			cos, sin := r.Cos[p*half:(p+1)*half], r.Sin[p*half:(p+1)*half]
373			for h := 0; h < heads; h++ {
374				seg := row[h*headDim : (h+1)*headDim]
375				for j := 0; j < half; j++ {
376					re, im := seg[2*j], seg[2*j+1]
377					seg[2*j] = re*cos[j] - im*sin[j]
378					seg[2*j+1] = re*sin[j] + im*cos[j]
379				}
380			}
381		}
382	}
383	
384	// attentionVariant recomputes the dumped attention with one rule changed:
385	// which kv head serves a query head, and whether the mask is causal.
386	func attentionVariant(t *testing.T, m *manifest, heads, kvHeads, hd int, kvOf func(int) int, causal bool) *Mat {
387		t.Helper()
388		q, k, v := loadRef(t, m, "q_roped"), loadRef(t, m, "k_roped"), loadRef(t, m, "v")
389		T := q.Rows
390		scale := float32(1 / math.Sqrt(float64(hd)))
391		out := NewMat(T, heads*hd)
392		for h := 0; h < heads; h++ {
393			kv := kvOf(h)
394			for i := 0; i < T; i++ {
395				last := T - 1
396				if causal {
397					last = i
398				}
399				scores := make([]float32, last+1)
400				max := float32(math.Inf(-1))
401				for s := 0; s <= last; s++ {
402					var dot float32
403					qv := q.Row(i)[h*hd : (h+1)*hd]
404					kr := k.Row(s)[kv*hd : (kv+1)*hd]
405					for c, qc := range qv {
406						dot += qc * kr[c]
407					}
408					scores[s] = dot * scale
409					if scores[s] > max {
410						max = scores[s]
411					}
412				}
413				var sum float32
414				for s := range scores {
415					scores[s] = float32(math.Exp(float64(scores[s] - max)))
416					sum += scores[s]
417				}
418				dst := out.Row(i)[h*hd : (h+1)*hd]
419				for s := range scores {
420					p := scores[s] / sum
421					vr := v.Row(s)[kv*hd : (kv+1)*hd]
422					for c, vv := range vr {
423						dst[c] += p * vv
424					}
425				}
426			}
427		}
428		return out
429	}
