183				more, err := t.encodeOrdinary(text)
184				if err != nil {
185					return nil, err
186				}
187				return append(ids, more...), nil
188			}
189			if at > 0 {
190				more, err := t.encodeOrdinary(text[:at])
191				if err != nil {
192					return nil, err
193				}
194				ids = append(ids, more...)
195			}
196			ids = append(ids, t.specialID[tok])
