202	// nextSpecial finds the earliest added token in text, longest match at that
203	// position, or -1.
204	func (t *Tokenizer) nextSpecial(text string) (int, string) {
205		best, bestTok := -1, ""
206		for _, s := range t.specials {
207			at := strings.Index(text, s)
208			if at < 0 || (best >= 0 && at >= best) {
209				continue
210			}
211			best, bestTok = at, s
212		}
213		return best, bestTok
214	}
215	
216	// encodeOrdinary runs the pre-tokenizer, the byte-level mapping and BPE.
217	func (t *Tokenizer) encodeOrdinary(text string) ([]int32, error) {
218		var ids []int32
219		for _, piece := range split(text, t.marks) {
220			var mapped strings.Builder
221			for i := 0; i < len(piece); i++ {
222				mapped.WriteRune(t.byteToRune[piece[i]])
223			}
224			for _, tok := range t.bpe(mapped.String()) {
225				id, ok := t.vocab[tok]
226				if !ok {
227					return nil, fmt.Errorf("tokenizer: %q is not in the vocabulary", tok)
228				}
229				ids = append(ids, id)
230			}
231		}
232		return ids, nil
233	}
234	
235	// bpe merges the symbols of one pre-token. Each round finds the lowest-rank
236	// adjacent pair anywhere in the word and merges every non-overlapping
237	// occurrence of it, which is the reference implementation's loop.
238	func (t *Tokenizer) bpe(word string) []string {
239		syms := make([]string, 0, len(word))
240		for _, r := range word {
241			syms = append(syms, string(r))
242		}
243		for len(syms) > 1 {
244			bestRank, bestAt := -1, -1
245			for i := 0; i+1 < len(syms); i++ {
246				rank, ok := t.ranks[syms[i]+"\x00"+syms[i+1]]
247				if !ok || (bestAt >= 0 && rank >= bestRank) {
248					continue
249				}
250				bestRank, bestAt = rank, i
251			}
252			if bestAt < 0 {
253				break
254			}
255			a, b := syms[bestAt], syms[bestAt+1]
256			out := syms[:0:0]
257			for i := 0; i < len(syms); {
258				if i+1 < len(syms) && syms[i] == a && syms[i+1] == b {
259					out = append(out, a+b)
260					i += 2
261					continue
262				}
263				out = append(out, syms[i])
264				i++
265			}
266			syms = out
267		}
268		return syms
269	}
270	
271	// Decode maps ids back to text. It exists for tests and for reading a dump;
272	// nothing in the pipeline decodes.
273	func (t *Tokenizer) Decode(ids []int32) (string, error) {
274		var out []byte
275		for _, id := range ids {
276			if id < 0 || int(id) >= len(t.tokens) || t.tokens[id] == "" {
277				return "", fmt.Errorf("tokenizer: id %d is not in the vocabulary", id)
278			}
279			tok := t.tokens[id]
280			if _, special := t.specialID[tok]; special {
281				out = append(out, tok...)
282				continue
283			}
284			for _, r := range tok {
285				b, ok := t.runeToByte[r]
286				if !ok {
287					return "", fmt.Errorf("tokenizer: token %q holds %q, which is not byte-level", tok, r)
288				}
289				out = append(out, b)
290			}
291		}
292		return string(out), nil
293	}
