func TestTemplate(t *testing.T) {
	m := loadManifest(t)
	for label, p := range m.Prompts {
		if got := TemplateT2I(p.Prompt); got != p.Rendered {
			t.Errorf("%s: template renders %q, want %q", label, got, p.Rendered)
		}
	}
	tok := loadTok(t)
	drop, err := DropTokens(tok)
	if err != nil {
		t.Fatal(err)
	}
	if drop != m.DropIdx {
