// Assemble builds the joint stream from the projected text (one row per VLM
// token, condition-image slot rows included) and the projected latents
// (condition images first, target last): text rows pass through, each slot
// expands to its 2x2 group's four latent rows.
func (m *Model) Assemble(txt, img *qwen.Mat, lay *Layout) (*qwen.Mat, error) {
	vlmLen := 0
	for _, s := range lay.VLMMask {
		if !s {
			vlmLen++
		}
	}
	slotRows := 0
	target := lay.ImgShapes[len(lay.ImgShapes)-1]
	targetTokens := target[0] * target[1] * target[2]
	for _, s := range lay.VLMMask {
		if s {
			slotRows++
		}
	}
	if want := vlmLen + slotRows - targetTokens/4; txt.Rows != want {
		return nil, fmt.Errorf("dit: %d text rows for a layout wanting %d", txt.Rows, want)
	}
	if img.Rows*1 != slotRows*4 {
		return nil, fmt.Errorf("dit: %d latent rows for %d slots", img.Rows, slotRows)
	}
	out := qwen.NewMat(lay.Seq(), txt.Cols)
	txtAt, imgAt, outAt := 0, 0, 0
	for i, slot := range lay.VLMMask {
		if slot {
			for j := 0; j < 4; j++ {
				copy(out.Row(outAt), img.Row(imgAt))
				outAt, imgAt = outAt+1, imgAt+1
			}
		} else {
			copy(out.Row(outAt), txt.Row(txtAt))
			outAt, txtAt = outAt+1, txtAt+1
		}
		// Condition-image slot rows of the text stream are consumed and
		// discarded: the latents overwrite them, per the reference's
		// scatter. Target slots (i >= the text's extent) have no text row.
		if slot && i < len(lay.VLMMask) && txtAt < txt.Rows && i < txtRowsExtent(lay, txt.Rows) {
			txtAt++
		}
	}
	_ = vlmLen
	return out, nil
}

// txtRowsExtent is how many leading VLM entries have text rows behind them:
// all of them except the appended target slots.
func txtRowsExtent(lay *Layout, txtRows int) int {
	target := lay.ImgShapes[len(lay.ImgShapes)-1]
	return len(lay.VLMMask) - target[0]*target[1]*target[2]/4
}

