119	// convTap, when set, is called with every convolution's input before it runs.
120	// It is how TestConvInputsFitFP16 measures the headroom the matrix-core
121	// convolution depends on -- stage 2's "absmax 497 through the whole decoder"
122	// as an assertion rather than as a memory -- without keeping a second copy
123	// of the decoder's graph in the test. Nothing in the library sets it.
124	var convTap func(c *Conv2D, x *Tensor)
125	
126	// Apply runs the convolution. Output is [N, OutC, H, W] for the 3x3 pad-1 and
127	// 1x1 pad-0 cases this decoder uses, both of which preserve spatial size.
128	func (c *Conv2D) Apply(x *Tensor) (*Tensor, error) {
129		if convTap != nil {
130			convTap(c, x)
131		}
132		if x.C != c.InC {
133			return nil, fmt.Errorf("vae: conv expects %d input channels, got %d", c.InC, x.C)
134		}
135		stride := c.stride()
136		outH := c.OutSize(x.H, c.KH)
137		outW := c.OutSize(x.W, c.KW)
138		if outH <= 0 || outW <= 0 {
139			return nil, fmt.Errorf("vae: conv on %s with kernel %dx%d pad %d leaves nothing", x, c.KH, c.KW, c.Pad)
140		}
