		t.Fatalf("%s: shape %v, want [1 C 1 H W]", name, sh)
	}
	out := zvae.NewTensor(1, sh[1], sh[3], sh[4])
	for i := range out.Data {
		out.Data[i] = math.Float32frombits(binary.LittleEndian.Uint32(raw[i*4:]))
