338:func DefaultGEMMPlan() GEMMPlan { return UniformGEMMPlan(GEMMWG128x256TiledSWZ8) }
342:func UniformGEMMPlan(k GEMMKernel) GEMMPlan {
351:func GEMMKernels() []GEMMKernel {
413:func (s blockSpec) load(set *safetensors.Set, cfg *Config) (*Block, error) {
432:func StackBlocks(cfg *Config) []blockSpec {
450:func specFor(prefix string) blockSpec {
457:func NewGPUStack(dev *vk.Device, set *safetensors.Set, cfg *Config, rope *RoPE, tokens int, plan GEMMPlan) (*GPUStack, error) {
