#version 450
// Z-Image's 3-D rotary embedding, applied in place to every head.
//
// The pairing is (2j, 2j+1): adjacent components form one complex number.
// The other convention in common use pairs j with j+headDim/2, and it
// produces a plausible-looking tensor that is wrong everywhere -- measured
// at 12.6 against a 2e-4 bound. The cos/sin table is precomputed on the host
// from the token ids, so this kernel is only the rotation.
//
// pc.inOff is the tensor, pc.wOff the [tokens, headDim/2] cos table with sin
// following it at pc.aux0.

#include "dit_common.glsl"

layout(local_size_x = 256) in;

void main() {
    uint idx = gl_GlobalInvocationID.x;
    uint pairs = pc.headDim / 2u;
    uint total = pc.tokens * pc.heads * pairs;
    if (idx >= total) {
        return;
    }
    uint j = idx % pairs;
    uint h = (idx / pairs) % pc.heads;
    uint token = idx / (pairs * pc.heads);

    float c = wbuf[pc.wOff + token * pairs + j];
    float s = wbuf[pc.aux0 + token * pairs + j];

    uint base = pc.inOff + token * pc.dim + h * pc.headDim + 2u * j;
    float re = act[base];
    float im = act[base + 1u];
    act[base] = re * c - im * s;
    act[base + 1u] = re * s + im * c;
}
#version 450

layout(local_size_x = 256) in;

layout(binding = 0) readonly buffer Src { float src[]; };
layout(binding = 1) writeonly buffer Dst { float dst[]; };

layout(push_constant) uniform PC {
    uint count;
} pc;

void main() {
    uint idx = gl_GlobalInvocationID.x;
    if (idx >= pc.count) {
        return;
    }
    dst[idx] = src[idx];
}

    float s = 0.0;
    for (uint c = t; c < pc.dim; c += WG) {
        s += act[src + c];
    }
    partial[t] = s;
    barrier();
    for (uint step = WG / 2u; step > 0u; step >>= 1) {
        if (t < step) {
            partial[t] += partial[t + step];
        }
        barrier();
    }
#if NO_MEAN
    float mean = 0.0;
#else
    float mean = partial[0] / n;
#endif
    barrier();

    float v2 = 0.0;
    for (uint c = t; c < pc.dim; c += WG) {
        float d = act[src + c] - mean;
        v2 += d * d;
    }
    partial[t] = v2;
    barrier();
    for (uint step = WG / 2u; step > 0u; step >>= 1) {
        if (t < step) {
            partial[t] += partial[t + step];
        }
        barrier();
    }
    float inv = inversesqrt(partial[0] / n + uintBitsToFloat(pc.eps));

    for (uint c = t; c < pc.dim; c += WG) {
        hact[dst + c] = float16_t((act[src + c] - mean) * inv * act[pc.aux0 + c]);
    }
}

void main() {
    uint r = gl_WorkGroupID.x;
    if (r >= pc.tokens) {
        return;
    }
    uint src = pc.inOff + r * pc.dim;
    uint dst = pc.outOff + r * pc.lda;
    for (uint c = gl_LocalInvocationID.x; c < pc.dim; c += 256u) {
        float v = act[src + c];
        if (pc.aux2 != 0u) {
            v *= act[pc.aux0 + c];
        }
        hact[dst + c] = float16_t(v);
    }
}
    barrier();
    for (uint s = 128u; s > 0u; s >>= 1) {
        if (t < s) {
            partial[t] += partial[t + s];
        }
        barrier();
    }
    float r = partial[0];
    barrier();
    return r;
}

void main() {
    uint spans = pc.dim / pc.span;
    uint token = gl_WorkGroupID.x / spans;
    uint span = gl_WorkGroupID.x % spans;
    uint t = gl_LocalInvocationID.x;
    if (token >= pc.tokens) {
        return;
    }
    uint base = token * pc.dim + span * pc.span;

