#version 450
#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
// Causal self-attention over Qwen-Image-2.1's text prefix, scalar.
//
// The 2.1 prefill's mask is block-causal: the target image block is
// internally bidirectional and sees everything, which is exactly what
// dit_attention_wmma.comp computes, but the text rows are causal among
// themselves. Rather than teach the matrix-core kernel a mask, the prefill
// runs it over the whole joint sequence and then this kernel recomputes the
// prefix rows' context correctly and overwrites them — the prefix is tens of
// tokens against thousands, so the wasted bidirectional rows and this whole
// pass together are noise (qimage/dit/gpu.go).
//
// It reads the same packed fp16 fragment planes the WMMA kernel reads (q at
// pc.inOff, k at pc.kOff both mode 0, v at pc.vOff mode 1, plane stride
// pc.aux1 tokens) and writes fp32 rows [0, pc.tokens) of the natural-layout
// context at pc.outOff. q arrives carrying 1/sqrt(headDim)*log2(e) from the
// pack, so the exponential is exp2, as in the WMMA kernel.
//
// One workgroup per (query row, head). pc.tokens is the prefix length and is
// capped by the scores array below; qimage/dit refuses longer prefixes
// rather than attending wrongly.

#include "dit_common.glsl"

layout(binding = 2) readonly buffer HAct { float16_t hact[]; };

#ifndef HEAD_DIM
#define HEAD_DIM 128
#endif
#define WG 128
#define MAX_PREFIX 512

layout(local_size_x = WG) in;

shared float qrow[HEAD_DIM];
shared float scores[MAX_PREFIX];
shared float partial[WG];

// Element (token m, component d) of a mode-0 fragment-tile plane
// (dit_pack_f16.comp): tile (m/16, d/16) is 256 contiguous halves, kt-major.
uint tile0(uint plane, uint m, uint d) {
    return plane + (m / 16u) * (16u * HEAD_DIM) + (d / 16u) * 256u + (m % 16u) * 16u + (d % 16u);
}

// Mode 1: the same tiles transposed, v's layout.
uint tile1(uint plane, uint m, uint d) {
    return plane + (m / 16u) * (16u * HEAD_DIM) + (d / 16u) * 256u + (d % 16u) * 16u + (m % 16u);
}

void main() {
    uint i = gl_WorkGroupID.x; // query row; keys are 0..i
    uint h = gl_WorkGroupID.y;
    uint t = gl_LocalInvocationID.x;
    if (i >= pc.tokens) {
        return;
    }
    uint plane = h * pc.aux1 * HEAD_DIM;

    for (uint d = t; d < HEAD_DIM; d += WG) {
        qrow[d] = float(hact[tile0(pc.inOff + plane, i, d)]);
    }
    barrier();

    // One thread per key: the prefix is small, the dot is the whole loop.
    for (uint j = t; j <= i; j += WG) {
        float s = 0.0;
        for (uint d = 0u; d < HEAD_DIM; d++) {
            s += qrow[d] * float(hact[tile0(pc.kOff + plane, j, d)]);
        }
        scores[j] = s;
    }
    barrier();

    // Row max, then exp2 and the denominator, tree-reduced over the lanes.
    float m = -3.4e38;
    for (uint j = t; j <= i; j += WG) {
        m = max(m, scores[j]);
    }
    partial[t] = m;
    barrier();
    for (uint s = WG / 2u; s > 0u; s >>= 1) {
        if (t < s) {
            partial[t] = max(partial[t], partial[t + s]);
        }
        barrier();
    }
    float rowMax = partial[0];
    barrier();

    float sum = 0.0;
    for (uint j = t; j <= i; j += WG) {
        float p = exp2(scores[j] - rowMax);
        scores[j] = p;
        sum += p;
    }
    partial[t] = sum;
    barrier();
    for (uint s = WG / 2u; s > 0u; s >>= 1) {
        if (t < s) {
            partial[t] += partial[t + s];
        }
        barrier();
    }
    float inv = 1.0 / partial[0];
    barrier();

    for (uint d = t; d < HEAD_DIM; d += WG) {
        float acc = 0.0;
        for (uint j = 0u; j <= i; j++) {
            acc += scores[j] * float(hact[tile1(pc.vOff + plane, j, d)]);
        }
        act[pc.outOff + i * pc.dim + h * HEAD_DIM + d] = acc * inv;
    }
}

