		}
		maxAbs, rel := stepRel(latents, loadMat(t, m, fmt.Sprintf("step%d_latents", i)))
		t.Logf("step %2d: %7.1f ms  max abs %.4g  rel %.3g", i, float64(walls[i].Microseconds())/1000, maxAbs, rel)
		if rel > gpuTol {
